-- +goose Up
-- Restates one account's costs left wrong by two rollup defects, both fixed in the code this ships with.
-- Every statement is scoped to the account and guarded on the exact value it replaces, so a row that has
-- moved since these values were computed is left alone, and a second run changes nothing.

-- 1. Case costs labelled per each. Before costs were restated into the stocking unit, the rollup wrote a
-- carton-of-eight total under the per-each label, and sales lines created then copied it: eight times
-- their COGS. The value is the carton's, so only the denominator moves. Lines are marked for the sales
-- fact refresher first, while the guard that finds them still matches.
INSERT INTO sales_fact_dirty (scope_type, scope_id, account_id, marked_at)
SELECT 'sales_order_line', sol.id, i.account_id, NOW(3)
FROM sales_order_line sol
JOIN item i ON i.id = sol.item_id AND i.account_id = 'ac_01gf7a8200f4r985f3r9x8mhkq'
JOIN item_category ic ON ic.id = i.item_category_id
JOIN unit_group ug ON ug.id = ic.unit_group_id
JOIN unit_group_unit ugu ON ugu.unit_group_id = ug.id
JOIN unit ct ON ct.id = ugu.unit_id AND ct.abbreviation = 'ct8ea'
JOIN rate ir ON ir.id = i.unit_cost_id
JOIN rate r ON r.id = sol.unit_cost_id
WHERE sol.created_at >= '2026-01-01' AND sol.created_at < '2026-09-03'
  AND r.id <> ir.id AND ir.value > 0
  AND r.numerator_unit_id = ir.numerator_unit_id
  AND r.denominator_unit_id = ug.base_unit_id AND ir.denominator_unit_id = ug.base_unit_id
  AND ABS(r.value / ir.value - ct.ratio_numerator / ct.ratio_denominator) <= 0.005 * ct.ratio_numerator / ct.ratio_denominator
ON DUPLICATE KEY UPDATE marked_at = VALUES(marked_at);

UPDATE rate r
JOIN sales_order_line sol ON sol.unit_cost_id = r.id
JOIN item i ON i.id = sol.item_id AND i.account_id = 'ac_01gf7a8200f4r985f3r9x8mhkq'
JOIN item_category ic ON ic.id = i.item_category_id
JOIN unit_group ug ON ug.id = ic.unit_group_id
JOIN unit_group_unit ugu ON ugu.unit_group_id = ug.id
JOIN unit ct ON ct.id = ugu.unit_id AND ct.abbreviation = 'ct8ea'
JOIN rate ir ON ir.id = i.unit_cost_id
SET r.denominator_unit_id = ct.id, r.updated_at = NOW(3)
WHERE sol.created_at >= '2026-01-01' AND sol.created_at < '2026-09-03'
  AND r.id <> ir.id AND ir.value > 0
  AND r.numerator_unit_id = ir.numerator_unit_id
  AND r.denominator_unit_id = ug.base_unit_id AND ir.denominator_unit_id = ug.base_unit_id
  AND ABS(r.value / ir.value - ct.ratio_numerator / ct.ratio_denominator) <= 0.005 * ct.ratio_numerator / ct.ratio_denominator;

-- 2. Labor timed per a unit the step does not produce in (seconds per case of fifty, or per pair on a
-- step making eaches) read as per each. `fix` is every item made by such a step and everything built
-- from one: its stored cost, and the corrected rollup's over the account's own production flow. Copies
-- of an item's cost are matched against the item's current value, so they are restated first and the
-- item last.

