-- An allocation's total is its quantity, carried into the unit its cost is per, times that cost.
UPDATE quantity tc
JOIN inventory_allocation a ON a.total_cost_id = tc.id
JOIN quantity q ON q.id = a.quantity_id
JOIN unit qu ON qu.id = q.unit_id
JOIN inventory_receipt x ON x.id = a.inventory_receipt_id
JOIN item i ON i.id = x.item_id AND i.account_id = 'ac_01gf7a8200f4r985f3r9x8mhkq'
JOIN rate ir ON ir.id = i.unit_cost_id
JOIN (
    SELECT '000e5285-4a9c-493f-853d-2c6ec647079c' AS item_id, 17.320263444444456299643813938893 AS old_value, '868369b1-325b-4048-843f-b72bfe52674a' AS old_unit, 1.730546819444445578755476742014 AS new_value, 'each' AS new_unit
    UNION ALL SELECT '0bec88ec-90ca-4e48-a44c-f17a712ef446', 20.871963600024855693002220006815, '868369b1-325b-4048-843f-b72bfe52674a', 1.995896079169773280703055278139, 'each'
    UNION ALL SELECT '18af7c55-c8d7-4b73-b5e9-558af9e26df7', 17.320263444444456299643813938893, '868369b1-325b-4048-843f-b72bfe52674a', 1.730546819444445578755476742014, 'each'
    UNION ALL SELECT '209c20dc-e5a7-4263-a29b-13a361b28ea2', 12.566307278888888788888888897363, 'each', 2.722364078888888788888888889488, 'each'
    UNION ALL SELECT '3990aaf3-51f0-4479-91e5-39525664391c', 17.320263444444456299643813938893, '868369b1-325b-4048-843f-b72bfe52674a', 1.730546819444445578755476742014, 'each'
    UNION ALL SELECT '3dc73821-a643-4308-823e-81fe528eab29', 12.158307278888888888888888897363, 'each', 2.314364078888888888888888889488, 'each'
    UNION ALL SELECT '4de65faf-16dd-45da-b6d1-6f03b4e88d4a', 12.058307278888888888888888897363, 'each', 2.214364078888888888888888889488, 'each'
    UNION ALL SELECT '59cf0a30-495e-4c4e-bc31-f554cc071797', 2.748065350392110544011328817486, 'pair', 2.466268797892110544011328817260, 'pair'
