    UNION ALL SELECT 'e3950d89-e24d-4405-9ddc-6cd4070ed52c', 2.493408631386666100547407413312, 'each', 2.211612078886666100547407413086, 'each'
    UNION ALL SELECT 'e3c5b375-92a1-4813-9413-fe9dc71e2c0d', 2.748065350392110544011328817486, 'each', 2.619673203169888321789106595161, 'each'
    UNION ALL SELECT 'e6318aca-b0cc-4b2e-92e5-6e8a740bdff1', 18.375206000024855693002220005138, '868369b1-325b-4048-843f-b72bfe52674a', 1.814848729169773280703055278034, 'each'
    UNION ALL SELECT 'e7e3c34c-4226-470a-92e5-c6cfeed58c30', 2.491281055947666099566884372836, 'each', 2.209484503447666099566884372611, 'each'
    UNION ALL SELECT 'fde5f614-019a-4eeb-9f45-0954175d43d4', 2.748065350392110544011328817486, 'each', 2.619673203169888321789106595161, 'each'
) fix ON fix.item_id = i.id AND ir.value = fix.old_value AND ir.denominator_unit_id = fix.old_unit
JOIN rate r ON r.id = a.unit_cost_id
JOIN unit nu ON nu.id = fix.new_unit
SET tc.value = q.value * (qu.ratio_numerator / qu.ratio_denominator) / (nu.ratio_numerator / nu.ratio_denominator) * fix.new_value,
    tc.updated_at = NOW(3)
WHERE r.id <> ir.id AND r.value = ir.value AND r.numerator_unit_id = ir.numerator_unit_id AND r.denominator_unit_id = ir.denominator_unit_id;

